def page(body,css):return '<!doctype html>\n<html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laboratorio HTML/CSS</title><link rel="stylesheet" href="style.css"></head><body>'+body+'</body></html>'
BASE='*{box-sizing:border-box}body{font:16px/1.5 system-ui;margin:2rem;color:#172033}button,input,select,textarea{font:inherit;margin:.3rem;padding:.5rem}label{display:block}a{color:#075ea8}'

def build_all():
    b=Book('html-css','HTML Living Standard; CSS moderno; Chromium120+',['https://html.spec.whatwg.org/','https://developer.mozilla.org/en-US/docs/Web/CSS'],'Browser moderno. Aprire index.html dalla cartella esportata. Per testare API soggette a secure context servire da localhost. Nessuna libreria esterna.')
    for title,body,css in ROWS:
        add(b,title,{'index.html':page(body,css),'style.css':BASE+css},commands='Start-Process .\\index.html',note='Apri index.html insieme a style.css nella stessa cartella. HTML contiene la struttura e gli attributi semantici; lo stile dimostra la regola CSS indicata dal titolo. Prova anche Tab, zoom200% e finestra stretta.',expected='La pagina visualizza il componente indicato; le regole CSS sono ispezionabili negli strumenti sviluppatore del browser.')
    title='Progetto: biblioteca responsive con filtri locali'
    html="<header><h1>Biblioteca del codice</h1><button id='theme'>Cambia tema</button></header><main><form role='search'><label for='q'>Cerca ricette</label><input id='q' type='search'><label for='stack'>Tecnologia</label><select id='stack'><option value=''>Tutte</option><option>Python</option><option>SQL</option><option>React</option></select></form><p id='status' role='status'></p><section id='cards' class='grid' aria-label='Risultati'></section></main><script src='app.js' defer></script>"
    js="const rows=[{title:'Leggere un file',stack:'Python',body:'Usare pathlib e UTF8.'},{title:'Unire due tabelle',stack:'SQL',body:'JOIN su chiave esterna.'},{title:'Gestire un form',stack:'React',body:'Stato e invio controllato.'}];const q=document.getElementById('q'),stack=document.getElementById('stack'),cards=document.getElementById('cards');function render(){cards.replaceChildren();const found=rows.filter(x=>x.title.toLowerCase().includes(q.value.toLowerCase())&&(!stack.value||x.stack===stack.value));for(const row of found){const a=document.createElement('article'),h=document.createElement('h2'),p=document.createElement('p');h.textContent=row.title;p.textContent=row.stack+' — '+row.body;a.append(h,p);cards.append(a)}document.getElementById('status').textContent=found.length+'risultati'}q.addEventListener('input',render);stack.addEventListener('change',render);document.querySelector('form').onsubmit=e=>e.preventDefault();document.getElementById('theme').onclick=()=>document.body.classList.toggle('dark');render();"
    css=BASE+'.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:1rem}article{padding:1.5rem;border:1px solid #9aa;border-radius:12px}header{display:flex;align-items:center;justify-content:space-between}.dark{background:#172033;color:#eef3fb}:focus-visible{outline:3px solid #1769c5;outline-offset:4px}'
    add(b,title,{'index.html':page(html,css),'style.css':css,'app.js':js,'README.md':'# Biblioteca locale\nAprire index.html. Tre schede, ricerca per titolo, filtro per stack, conteggio risultati e tema chiaro/scuro. Prova: cercando file rimane1scheda; scegliendo SQL e query vuota rimaneJOIN. Funziona senza rete.'},project=True,section='Progetti completi',commands='Start-Process .\\index.html',note='Una pagina autonoma integra ricerca, filtri, card responsive e tema. Il rendering usa textContent per i dati; nessuna dipendenza o richiesta esterna.',expected='3schede iniziali; cercando file resta1risultato. Il filtro SQL mostra una sola scheda.')
    from web_lifecycle import apply
    apply(b)
    assert len(b.recipes)==45,len(b.recipes)
    b.save()

if __name__=='__main__':build_all()
